INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 1, 2, 'Khi tiếp nhận yêu cầu từ khách gửi hàng hoặc Điều hành, tài xế dùng kỹ thuật Paraphrasing nhằm mục đích gì?', 'When receiving a request from a customer or Operations, why does the driver use Paraphrasing?', '接收客户或调度部门的要求时，司机使用复述确认技巧的目的是什么？', 'Im lặng và tự xử lý theo thói quen', 'Nhắc lại các chi tiết quan trọng (địa chỉ, mã hàng, ghi chú) để xác nhận chính xác 100%', 'Ngắt lời khách khi đang giải thích', NULL, NULL, NULL, 'Stay silent and act out of habit', 'Repeat key details (address, code, notes) to confirm 100% accuracy', 'Interrupt the customer while explaining', NULL, NULL, NULL, '保持沉默按习惯处理', '复述重要细节（地址、货号、备注）以确保100%准确', '在客户解释时打断对方', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 1, 2, 'Khi khách hàng đang rất vội vã hoặc cáu gắt, tài xế SF nên lắng nghe như thế nào?', 'When a customer is rushed or irritated, how should an SF driver listen?', '当客户非常匆忙或情绪暴躁时，顺丰司机应如何倾听？', 'Lập tức tranh cãi để bảo vệ bản thân', 'Bình tĩnh lắng nghe, ghi nhận nhanh thông tin cốt lõi và tập trung hoàn thành thủ tục bàn giao', 'Bỏ đi không hỗ trợ nữa', NULL, NULL, NULL, 'Argue immediately to defend themselves', 'Listen calmly, quickly note key info, and focus on completing the handover', 'Walk away and stop assisting', NULL, NULL, NULL, '立即争辩以自我保护', '冷静倾听，快速记录核心信息，专注完成交接手续', '直接离开不再提供协助', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 1, 2, 'Hành động nào thể hiện tài xế LẮNG NGHE CHỦ ĐỘNG khi nhận bưu kiện?', 'Which action shows ACTIVE LISTENING when receiving a parcel?', '收件时哪种行为体现了「主动倾听」？', 'Nhìn ra chỗ khác khi khách đang nói', 'Tập trung 100%, gật đầu xác nhận và không ngắt lời khách', 'Vừa bấm điện thoại chơi game vừa nghe', NULL, NULL, NULL, 'Looking away while the customer speaks', 'Giving 100% attention, nodding to confirm, and not interrupting', 'Playing on the phone while listening', NULL, NULL, NULL, '客户说话时看向别处', '100%专注、点头确认且不打断客户', '一边玩手机一边听', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 1, 1, 'Khi bộ phận Điều hành giao lệnh đi lấy hàng gấp phát sinh, tài xế cần phản hồi thế nào?', 'When Operations issues an urgent pickup order, how should the driver respond?', '调度部门下达紧急取件指令时，司机应如何回应？', 'Ghi nhận, xác nhận lại lộ trình, thời gian Cut-off và yêu cầu đặc biệt của kiện hàng', 'Phớt lờ tin nhắn điều hành', 'Khi nào tiện thì đến không cần báo lại', NULL, NULL, NULL, 'Note it and confirm the route, cut-off time, and special requirements', 'Ignore the message from Operations', 'Show up whenever convenient without reporting back', NULL, NULL, NULL, '记录并确认路线、截单时间和特殊要求', '忽略调度的消息', '方便时再去，无需回复', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 1, 2, 'Lợi ích lớn nhất của việc không ngắt lời khách hàng khi nghe khiếu nại là gì?', 'What is the biggest benefit of not interrupting a customer during a complaint?', '倾听投诉时不打断客户的最大好处是什么？', 'Tốn thời gian làm việc', 'Giúp khách hàng giải tỏa cảm xúc và thu thập chính xác nguyên nhân sự cố', 'Để khách tự nói một mình', NULL, NULL, NULL, 'It wastes working time', 'It helps the customer vent and lets you gather the exact cause accurately', 'Letting the customer talk to themselves', NULL, NULL, NULL, '浪费工作时间', '帮助客户宣泄情绪并准确了解问题原因', '让客户自言自语', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 1, 1, 'Mô hình HURIER về kỹ năng lắng nghe hiệu quả do ai phát triển?', 'Who developed the HURIER model of effective listening?', '有效倾听的HURIER模型是由谁提出的？', 'Judi Brownell (Đại học Cornell)', 'Albert Mehrabian', 'John Boyd (Không quân Hoa Kỳ)', NULL, NULL, NULL, 'Judi Brownell (Cornell University)', 'Albert Mehrabian', 'John Boyd (USAF)', NULL, NULL, NULL, 'Judi Brownell（康奈尔大学）', 'Albert Mehrabian', 'John Boyd（美国空军）', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 1, 3, 'Theo nghiên cứu của Ralph Nichols, người nghe thường chỉ nhớ được bao nhiêu % nội dung ngay sau khi nghe?', 'According to Ralph Nichols'' research, how much of what they hear do listeners typically retain right after listening?', '根据Ralph Nichols的研究，听者听完后通常能记住多少内容？', 'Gần như 100%', '70-90%', 'Khoảng 25-50%', NULL, NULL, NULL, 'Nearly 100%', '70-90%', 'About 25-50%', NULL, NULL, NULL, '接近100%', '70%-90%', '约25%-50%', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 1, 2, 'Nguyên tắc 7-38-55 của Albert Mehrabian nhấn mạnh điều gì trong giao tiếp tình huống nhạy cảm?', 'What does Mehrabian''s 7-38-55 rule emphasize in sensitive communication?', 'Mehrabian的7-38-55法则在敏感沟通情境中强调了什么？', 'Nội dung lời nói quan trọng hơn tất cả', 'Thái độ, giọng điệu và ngôn ngữ cơ thể ảnh hưởng đến cảm nhận khách hàng nhiều hơn lời nói', 'Chỉ cần nói đúng ngữ pháp là đủ', NULL, NULL, NULL, 'Spoken content matters more than anything else', 'Attitude, tone, and body language shape perception more than words themselves', 'Correct grammar alone is sufficient', NULL, NULL, NULL, '说话内容比一切都重要', '态度、语气和肢体语言比话语本身更能影响客户感受', '只要语法正确就足够了', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 1, 1, '"Purple Promise" là cam kết dịch vụ nổi tiếng của doanh nghiệp chuyển phát nào?', '"Purple Promise" is a well-known service commitment of which courier company?', '「紫色承诺」是哪家快递企业著名的服务承诺？', 'FedEx', 'DHL', 'UPS', NULL, NULL, NULL, 'FedEx', 'DHL', 'UPS', NULL, NULL, NULL, '联邦快递 (FedEx)', 'DHL', 'UPS', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 1, 3, 'Việc các hãng như Giao Hàng Nhanh, Viettel Post, J&T Express gọi điện xác nhận trước khi giao hàng thể hiện điều gì?', 'What does it show when carriers like Giao Hang Nhanh, Viettel Post, and J&T Express call to confirm before delivery?', 'Giao Hang Nhanh、Viettel Post、J&T Express等企业在派送前致电确认体现了什么？', 'Thủ tục rườm rà không cần thiết', 'Chỉ để quảng cáo dịch vụ', 'Một hình thức lắng nghe chủ động giúp giảm tỷ lệ giao hàng thất bại', NULL, NULL, NULL, 'An unnecessary, cumbersome procedure', 'Just advertising the service', 'A form of active listening that reduces delivery failure rate', NULL, NULL, NULL, '不必要的繁琐手续', '只是为了宣传服务', '一种主动倾听形式，有助于降低派送失败率', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 2, 2, 'Thao tác nào sau đây là BẮT BUỘC khi vận chuyển và bưng bê kiện hàng của khách?', 'Which action is MANDATORY when carrying a customer''s parcel?', '搬运客户包裹时，以下哪项操作是必须的？', 'Kéo lê thùng hàng trên sàn cho nhẹ sức', 'Bưng bê bằng hai tay, đặt nhẹ nhàng, chủ động hỗ trợ bưng hàng giúp khách', 'Ném nhẹ kiện hàng vào góc kho cho nhanh', NULL, NULL, NULL, 'Drag the box on the floor to save effort', 'Carry with both hands, place gently, and proactively help the customer', 'Toss the parcel into a corner to save time', NULL, NULL, NULL, '在地上拖拽货箱以省力', '双手搬运、轻放，并主动帮助客户', '为图快而将包裹扔进角落', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 2, 2, 'Khi khách hàng gửi kiện hàng nặng hoặc cồng kềnh, thái độ chuẩn mực của tài xế SF là gì?', 'When a customer sends a heavy or bulky parcel, what is the correct attitude for an SF driver?', '客户寄送笨重或大件货物时，顺丰司机应有的标准态度是什么？', 'Tỏ thái độ khó chịu và yêu cầu khách tự khiêng', 'Vui vẻ, lịch sự và chủ động hỗ trợ bưng bê xếp dỡ giúp khách', 'Từ chối phục vụ nếu không có tiền bồi dưỡng', NULL, NULL, NULL, 'Show annoyance and ask the customer to carry it themselves', 'Be cheerful, polite, and proactively help carry/unload it', 'Refuse service unless given a tip', NULL, NULL, NULL, '表现出不耐烦并要求客户自己搬', '愉快、礼貌并主动协助搬运卸货', '没有小费就拒绝服务', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 2, 1, 'Khi gặp khách hàng trực tiếp, quy chuẩn diện mạo chuyên nghiệp của nhân viên SF là gì?', 'When meeting customers directly, what is the professional appearance standard for SF staff?', '直接接触客户时，顺丰员工的专业仪容标准是什么？', 'Đồng phục gọn gàng, đeo thẻ nhân viên, xe và thùng hàng sạch sẽ', 'Mặc quần đùi áo may ba cho thoải mái', 'Không cần đeo thẻ nhân viên', NULL, NULL, NULL, 'Tidy uniform, employee badge worn, clean vehicle and cargo box', 'Wear shorts and a tank top for comfort', 'No need to wear the employee badge', NULL, NULL, NULL, '整洁制服、佩戴工牌、车辆和货厢干净', '为了舒适穿短裤背心', '无需佩戴工牌', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 2, 2, 'Chủ đề nào tài xế KHÔNG NÊN bàn luận với khách hàng trong quá trình giao nhận hàng?', 'Which topic should a driver NOT discuss with customers during handover?', '在收发货过程中，司机不应与客户讨论哪类话题？', 'Hướng dẫn đóng gói bưu kiện', 'Chính trị, tôn giáo, chuyện đời tư cá nhân', 'Xác nhận thời gian nhận hàng', NULL, NULL, NULL, 'Packaging guidance', 'Politics, religion, personal life', 'Confirming the receiving time', NULL, NULL, NULL, '包装指导', '政治、宗教、个人隐私', '确认收货时间', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 2, 2, 'Khi bàn giao hàng hóa cho khách, tài xế nên có lời chào và cử chỉ như thế nào?', 'When handing over the parcel, how should the driver greet and behave?', '交货给客户时，司机应有怎样的问候和举止？', 'Mặt lạnh lùng không nói câu nào', 'Chào hỏi lịch sự, đưa chứng từ/thiết bị bằng hai tay và nở nụ cười nhẹ', 'Quăng giấy tờ lên bàn rồi đi', NULL, NULL, NULL, 'A cold expression with no words', 'Greet politely, hand documents/device with both hands, and smile lightly', 'Throw the papers on the table and leave', NULL, NULL, NULL, '面无表情一言不发', '礼貌问候，双手递交单据/设备并微笑', '把单据扔在桌上就离开', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 2, 2, 'Mô hình SERVQUAL do ai đề xuất, dùng để đánh giá chất lượng dịch vụ?', 'Who proposed the SERVQUAL model used to assess service quality?', '用于评估服务质量的SERVQUAL模型是由谁提出的？', 'Bruce Tuckman', 'Parasuraman, Zeithaml & Berry', 'John Boyd', NULL, NULL, NULL, 'Bruce Tuckman', 'Parasuraman, Zeithaml & Berry', 'John Boyd', NULL, NULL, NULL, 'Bruce Tuckman', 'Parasuraman, Zeithaml & Berry', 'John Boyd', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 2, 3, 'Yếu tố nào sau đây KHÔNG thuộc 5 thành phần của mô hình SERVQUAL?', 'Which of the following is NOT one of the 5 SERVQUAL dimensions?', '以下哪项不属于SERVQUAL模型的五个维度？', 'Sự đồng cảm (Empathy)', 'Yếu tố hữu hình (Tangibles)', 'Lợi nhuận (Profitability)', NULL, NULL, NULL, 'Empathy', 'Tangibles', 'Profitability', NULL, NULL, NULL, '同理心 (Empathy)', '有形性 (Tangibles)', '盈利能力 (Profitability)', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 2, 1, 'Trong ngành chuyển phát, yếu tố "Tangibles" (hữu hình) của SERVQUAL thể hiện rõ nhất qua điều gì?', 'In courier services, the "Tangibles" dimension of SERVQUAL is best reflected by what?', '在快递行业中，SERVQUAL的「有形性」维度最明显体现在什么方面？', 'Tác phong, đồng phục, tình trạng xe và bưu kiện của tài xế', 'Giá cước vận chuyển', 'Số lượng chi nhánh của công ty', NULL, NULL, NULL, 'The driver''s conduct, uniform, and condition of vehicle/parcel', 'The shipping fee', 'The number of company branches', NULL, NULL, NULL, '司机的仪态、制服及车辆/货物状况', '运费价格', '公司分支机构数量', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 2, 2, 'Chương trình đào tạo "340 Methods" chuẩn hóa thao tác tài xế là của doanh nghiệp nào?', 'The "340 Methods" training program that standardizes driver procedures belongs to which company?', '标准化司机操作流程的「340种方法」培训计划属于哪家企业？', 'DHL', 'UPS', 'Grab Express', NULL, NULL, NULL, 'DHL', 'UPS', 'Grab Express', NULL, NULL, NULL, 'DHL', 'UPS', 'Grab Express', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 2, 1, 'Khái niệm "last-mile touchpoint" (điểm chạm cuối cùng) trong logistics có nghĩa là gì?', 'What does the "last-mile touchpoint" concept mean in logistics?', '物流中「最后一公里触点」的概念是什么意思？', 'Thời điểm duy nhất khách hàng gặp trực tiếp đại diện thương hiệu (tài xế) trong toàn chuỗi cung ứng', 'Điểm giao hàng xa nhất trong thành phố', 'Chặng vận chuyển đường dài giữa các kho', NULL, NULL, NULL, 'The one moment a customer meets the brand''s human representative (the driver) in the whole supply chain', 'The farthest delivery point in a city', 'The long-haul leg between warehouses', NULL, NULL, NULL, '客户在整个供应链中唯一直接接触品牌代表（司机）的时刻', '城市中最远的派送点', '仓库之间的长途运输段', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 3, 2, 'Nguyên tắc xếp hàng hóa nào đúng quy chuẩn an toàn trên xe tải?', 'Which cargo-loading principle follows safety standards for trucks?', '以下哪种货物装载方式符合货车安全规范？', 'Xếp hàng nặng lên trên hàng nhẹ để đè giữ hàng', 'Hàng nặng xếp dưới, hàng nhẹ/dễ vỡ xếp trên và chằng buộc chắc chắn', 'Chất đống tự do miễn sao vừa thùng xe', NULL, NULL, NULL, 'Put heavy items on top of light items to hold them down', 'Heavy items at the bottom, light/fragile items on top, all secured tightly', 'Pile freely as long as it fits the cargo box', NULL, NULL, NULL, '把重物压在轻物上方以固定货物', '重物放下方、轻/易碎物放上方并牢固捆绑', '只要能塞进货厢，随意堆放即可', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 3, 2, 'Việc giữ khoảng cách an toàn và quan sát tầm xa (15-20 giây) giúp ích gì cho chất lượng hàng hóa?', 'How does keeping a safe distance and scanning 15-20 seconds ahead help cargo quality?', '保持安全车距并提前15-20秒观察路况对货物质量有什么帮助？', 'Giúp xe chạy nhanh hơn', 'Giúp tài xế chủ động giảm tốc nhẹ nhàng, tránh phanh gấp làm va đập đổ vỡ hàng', 'Không liên quan đến hàng hóa', NULL, NULL, NULL, 'It makes the vehicle go faster', 'It lets the driver slow down gently, avoiding sudden braking that damages cargo', 'It has nothing to do with cargo', NULL, NULL, NULL, '能让车辆行驶更快', '让司机能平稳减速，避免急刹造成货物碰撞损坏', '与货物无关', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 3, 2, 'Trời mưa to, đường trơn trượt, khoảng cách an toàn (quy tắc giây) nên tăng lên như thế nào?', 'In heavy rain and slippery roads, how should the safe-distance rule change?', '大雨天路面湿滑时，安全距离（秒数法则）应如何调整？', 'Giữ nguyên 3 giây', 'Tăng lên tối thiểu 6 giây để phòng tránh va chạm và giật phanh gấp', 'Giảm xuống 1 giây', NULL, NULL, NULL, 'Keep it at 3 seconds', 'Increase to at least 6 seconds to prevent collisions and sudden braking', 'Reduce it to 1 second', NULL, NULL, NULL, '保持3秒不变', '增加到至少6秒以防碰撞和急刹', '减少到1秒', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 3, 1, 'Trước khi bắt đầu chuyến xe vận chuyển, tài xế BẮT BUỘC phải kiểm tra điều gì ở thùng xe?', 'Before starting a trip, what must the driver check on the cargo box?', '出车前，司机必须检查货厢的哪些方面？', 'Thùng xe sạch, khô ráo, không rò rỉ nước và đã khóa/niêm phong an toàn', 'Chỉ cần xe chạy được là được', 'Không cần kiểm tra thùng xe', NULL, NULL, NULL, 'The box is clean, dry, leak-free, and safely locked/sealed', 'Only that the vehicle can run', 'No need to check the cargo box', NULL, NULL, NULL, '货厢干净、干燥、不漏水，并已安全上锁/封条', '只要车能开就行', '无需检查货厢', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 3, 1, 'Thao tác nào bị CẤM TUYỆT ĐỐI khi đang điều khiển phương tiện vận chuyển bưu kiện?', 'Which action is strictly PROHIBITED while driving?', '驾驶运输车辆时，绝对禁止哪种操作？', 'Sử dụng điện thoại di động bằng tay để nghe gọi, nhắn tin', 'Quan sát gương chiếu hậu', 'Giữ đúng tốc độ quy định', NULL, NULL, NULL, 'Using a handheld phone to call or text', 'Checking the rearview mirror', 'Maintaining the correct speed', NULL, NULL, NULL, '用手持手机打电话或发短信', '查看后视镜', '保持规定车速', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 3, 1, 'Quy tắc khoảng cách an toàn 3 giây (6 giây khi trời xấu) được khuyến nghị bởi tổ chức nào?', 'Which organization recommends the 3-second (6-second in bad weather) following distance rule?', '3秒（恶劣天气6秒）安全车距法则是哪个机构建议的？', 'NHTSA (Cơ quan An toàn Giao thông Đường bộ Quốc gia Hoa Kỳ)', 'Tổ chức Y tế Thế giới (WHO)', 'Liên đoàn Bóng đá Thế giới (FIFA)', NULL, NULL, NULL, 'NHTSA (U.S. National Highway Traffic Safety Administration)', 'World Health Organization (WHO)', 'FIFA', NULL, NULL, NULL, 'NHTSA（美国国家公路交通安全管理局）', '世界卫生组织（WHO）', '国际足联（FIFA）', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 3, 3, 'Nguyên tắc nào sau đây KHÔNG thuộc 5 nguyên tắc của Smith System trong lái xe phòng vệ?', 'Which of the following is NOT one of the 5 Smith System defensive-driving principles?', '以下哪项不属于史密斯系统防御性驾驶的五大原则？', 'Get the Big Picture (Quan sát toàn cảnh)', 'Leave Yourself an Out (Chừa đường thoát hiểm)', 'Maximize Speed (Tối đa tốc độ)', NULL, NULL, NULL, 'Get the Big Picture', 'Leave Yourself an Out', 'Maximize Speed', NULL, NULL, NULL, '纵观全局 (Get the Big Picture)', '留有退路 (Leave Yourself an Out)', '将速度最大化 (Maximize Speed)', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 3, 2, 'Việc xếp hàng nặng ở dưới đáy thùng xe dựa trên nguyên lý vật lý nào?', 'Placing heavy items at the bottom of the cargo box is based on which physics principle?', '将重物放置在货厢底部依据的是什么物理原理？', 'Lực ma sát cực đại', 'Trọng tâm thấp (low center of gravity) giúp xe ổn định khi cua/phanh', 'Định luật bảo toàn năng lượng', NULL, NULL, NULL, 'Maximum friction force', 'Low center of gravity, which stabilizes the vehicle during turns/braking', 'Conservation of energy', NULL, NULL, NULL, '最大摩擦力', '低重心原理，使车辆转弯/刹车时更稳定', '能量守恒定律', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 3, 1, 'Đội xe của doanh nghiệp nào được ghi nhận có tỷ lệ tai nạn/triệu dặm thấp nhờ huấn luyện an toàn nội bộ nghiêm ngặt ("seatbelt-key-mirror")?', 'Which company''s fleet is recognized for a low accident rate per million miles thanks to strict internal safety training ("seatbelt-key-mirror")?', '哪家企业的车队因严格的内部安全培训（「安全带-钥匙-后视镜」）而以百万英里事故率低而闻名？', 'UPS', 'Ninja Van', 'Amazon Logistics', NULL, NULL, NULL, 'UPS', 'Ninja Van', 'Amazon Logistics', NULL, NULL, NULL, 'UPS', 'Ninja Van', '亚马逊物流', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 3, 3, 'Tại Việt Nam, Viettel Post và J&T Express trang bị camera hành trình (dashcam) và GPS giám sát tốc độ nhằm mục đích chính là gì?', 'In Vietnam, why do Viettel Post and J&T Express equip trucks with dashcams and GPS speed monitoring?', '在越南，Viettel Post和J&T Express为货车配备行车记录仪和GPS测速系统的主要目的是什么？', 'Để quay video giải trí cho tài xế', 'Chỉ để theo dõi vị trí giao hàng', 'Nhắc nhở tài xế duy trì khoảng cách và tốc độ an toàn theo thời gian thực', NULL, NULL, NULL, 'To record entertainment videos for drivers', 'Only to track delivery location', 'To remind drivers to keep safe distance and speed in real time', NULL, NULL, NULL, '为司机录制娱乐视频', '仅用于追踪派送位置', '实时提醒司机保持安全车距与车速', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 4, 2, 'Phát hiện vỏ bưu kiện bị móp méo/rách khi chuẩn bị giao cho khách, tài xế nên xử lý ra sao?', 'If you find the parcel dented/torn right before delivery, what should you do?', '派送前发现包裹外皮凹陷/破损，司机应如何处理？', 'Giấu vết móp và giao thật nhanh rồi đi', 'Bình tĩnh giải thích, cùng khách kiểm tra thực tế, chụp ảnh và báo CS/Điều hành hỗ trợ', 'Đổ lỗi cho nhân viên chia chọn kho', NULL, NULL, NULL, 'Hide the damage and deliver quickly, then leave', 'Calmly explain, inspect it together with the customer, take photos, and notify CS/Operations', 'Blame the warehouse sorting staff', NULL, NULL, NULL, '隐藏破损痕迹并快速交货离开', '冷静解释，与客户一起检查实际情况，拍照并上报客服/调度', '归咎于仓库分拣人员', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 4, 2, 'Khi gặp kẹt xe nghiêm trọng có nguy cơ trễ giờ giao hàng đã hẹn, tài xế cần làm gì?', 'During heavy traffic that risks missing the scheduled delivery, what should the driver do?', '遇到严重拥堵可能延误约定送货时间时，司机应该怎么做？', 'Im lặng, khi nào đến nơi mới giải thích', 'Chủ động gọi điện xin lỗi khách hàng, báo thời gian dự kiến trễ và cập nhật điều hành', 'Tự ý hủy đơn hàng trên hệ thống', NULL, NULL, NULL, 'Stay silent and explain only upon arrival', 'Proactively call to apologize, give the expected delay time, and update Operations', 'Cancel the order in the system on their own', NULL, NULL, NULL, '保持沉默，到达后再解释', '主动致电道歉，告知预计延误时间并更新调度', '擅自在系统中取消订单', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 4, 2, 'Phương tiện gặp sự cố hỏng hóc giữa đường, ưu tiên số 1 của tài xế là gì?', 'If the vehicle breaks down mid-route, what is the driver''s number-1 priority?', '车辆在途中发生故障，司机的第一优先事项是什么？', 'Bỏ xe đi về', 'Đảm bảo an toàn giao thông và bảo vệ an toàn cho toàn bộ hàng hóa trên xe', 'Mở thùng xe ra cho thoáng', NULL, NULL, NULL, 'Abandon the vehicle and go home', 'Ensure traffic safety and protect the safety of all cargo on board', 'Open the cargo box for ventilation', NULL, NULL, NULL, '弃车回家', '确保交通安全并保护车上所有货物的安全', '打开货厢通风', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 4, 2, 'Khách hàng từ chối nhận hàng do đơn hàng bị trễ so với cam kết, tài xế nên phản ứng thế nào?', 'If a customer refuses to accept a late delivery, how should the driver react?', '因订单延误客户拒收时，司机应如何应对？', 'Quát mắng khách hàng', 'Lắng nghe, xin lỗi chân thành về sự chậm trễ và lập biên bản/báo về CS xử lý', 'Vứt hàng lại trước cửa nhà khách', NULL, NULL, NULL, 'Yell at the customer', 'Listen, sincerely apologize for the delay, and file a report/notify CS to handle it', 'Leave the parcel at the door and go', NULL, NULL, NULL, '斥责客户', '倾听并真诚就延误道歉，填写记录/上报客服处理', '把货物丢在客户门口离开', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 4, 1, 'Với hàng xuất khẩu, khi khách hàng không đồng ý cho nhân viên mở kiểm tra hàng đối chiếu Invoice, nhân viên nên giải thích lý do chính là gì?', 'For export cargo, when a customer refuses to let staff open the parcel to check it against the Invoice, what is the main reason staff should explain?', '对于出口货物，客户不同意员工开箱核对发票时，员工应说明的主要理由是什么？', 'Để hỗ trợ hàng hoá được thông quan và xuất khẩu nhanh nhất, kịp thời điều chỉnh nếu thông tin khai báo trên Invoice có sai lệch', 'Vì quy định bắt buộc phải mở tất cả các kiện hàng không có ngoại lệ', 'Để kiểm tra xem khách có gian lận hay không', NULL, NULL, NULL, 'To help the shipment clear customs and be exported as fast as possible, and promptly fix any mismatch in the Invoice declaration', 'Because regulations require opening every parcel with no exceptions', 'To check whether the customer is committing fraud', NULL, NULL, NULL, '为协助货物尽快通关出口，并在发票申报信息有误时及时调整', '因为规定要求必须无例外地打开所有包裹', '为了检查客户是否存在欺诈行为', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 4, 3, 'Theo quy định xuất khẩu, hàng nào sau đây thuộc danh mục CẤM vận chuyển?', 'Under export regulations, which of the following is classified as PROHIBITED for shipment?', '根据出口规定，以下哪项属于禁止运输的物品？', 'Hàng dễ vỡ đã được chèn lót cẩn thận', 'Hàng đóng pallet gỗ có kèm chứng thư hun trùng', 'Pin Lithium-ion/kim loại rời, ngà voi, sừng và các sản phẩm từ động vật hoang dã', NULL, NULL, NULL, 'Fragile goods that have been carefully cushioned', 'Wooden pallet cargo with a fumigation certificate attached', 'Loose lithium-ion/lithium-metal batteries, ivory, horns, and wildlife products', NULL, NULL, NULL, '已妥善缓冲包装的易碎品', '附有熏蒸证书的木质栈板货物', '散装锂离子/锂金属电池、象牙、犀牛角及野生动物制品', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 4, 2, 'Lô hàng xuất khẩu có giá trị khai báo trên 5.000.000 VNĐ hoặc khối lượng trên 50kg thì cần thực hiện thủ tục gì?', 'What procedure is required for an export shipment declared over 5,000,000 VND or weighing over 50kg?', '申报价值超过500万越南盾或货重超过50公斤的出口货物需要办理什么手续？', 'Không cần thủ tục gì thêm', 'Bắt buộc lên tờ khai hải quan xuất khẩu theo quy định', 'Chỉ cần dán thêm nhãn cảnh báo', NULL, NULL, NULL, 'No additional procedure is needed', 'An export customs declaration must be filed as required', 'Only a warning label needs to be attached', NULL, NULL, NULL, '不需要额外手续', '必须按规定办理出口报关单', '只需贴上警示标签即可', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 4, 1, 'Hàng đóng kiện/pallet gỗ khi xuất khẩu bắt buộc phải kèm theo giấy tờ nào?', 'When exporting wooden crate/pallet cargo, which document must accompany it?', '出口木质栈板/木箱货物时必须附带哪份文件？', 'Chứng thư hun trùng (Fumigation Certificate) bản gốc', 'Giấy bảo hành sản phẩm', 'Hóa đơn mua hàng của khách', NULL, NULL, NULL, 'An original Fumigation Certificate', 'A product warranty certificate', 'The customer''s purchase receipt', NULL, NULL, NULL, '熏蒸证书（Fumigation Certificate）原件', '产品保修单', '客户的购物收据', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 4, 3, 'Theo quy định hiện hành của hãng bay, hàng đóng pallet tạm thời KHÔNG được xuất qua sân bay nào?', 'Under current airline regulations, palletized cargo is currently NOT accepted for export via which airports?', '根据航空公司现行规定，栈板货物目前不能经由哪些机场出口？', 'Chỉ áp dụng cho sân bay nội địa Việt Nam', 'HAN và SGN', 'SZX (Thâm Quyến) và PVG (Phố Đông – Thượng Hải)', NULL, NULL, NULL, 'Only applies to domestic Vietnamese airports', 'HAN and SGN', 'SZX (Shenzhen) and PVG (Shanghai Pudong)', NULL, NULL, NULL, '仅适用于越南国内机场', '河内（HAN）和胡志明市（SGN）', '深圳（SZX）和上海浦东（PVG）', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 4, 1, 'Trong mô hình xử lý khiếu nại LAST, bước đầu tiên (L) là gì?', 'In the LAST complaint-handling model, what is the first step (L)?', '在LAST投诉处理模型中，第一步（L）是什么？', 'Listen – Lắng nghe trọn vẹn vấn đề của khách', 'Leave – Rời khỏi hiện trường', 'Loan – Cho khách vay tiền', NULL, NULL, NULL, 'Listen – fully hear the customer''s issue', 'Leave – leave the scene', 'Loan – lend the customer money', NULL, NULL, NULL, 'Listen – 充分倾听客户的问题', 'Leave – 离开现场', 'Loan – 借钱给客户', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 5, 1, 'Theo quy chuẩn an toàn lái xe, tài xế không được lái xe liên tục quá bao nhiêu giờ?', 'Per safety regulations, drivers should not drive continuously for more than how many hours?', '根据安全驾驶规范，司机连续驾驶不得超过多少小时？', 'Không quá 4 giờ liên tục', 'Không quá 6 giờ liên tục', 'Không quá 8 giờ liên tục', NULL, NULL, NULL, 'No more than 4 hours straight', 'No more than 6 hours straight', 'No more than 8 hours straight', NULL, NULL, NULL, '不超过连续4小时', '不超过连续6小时', '不超过连续8小时', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 5, 1, 'Việc sắp xếp thứ tự các điểm giao/nhận hàng theo tuyến đường tối ưu trước khi xuất kho mang lại lợi ích gì?', 'What benefit comes from sequencing delivery/pickup points on an optimal route before departure?', '出库前按最优路线安排取送货点顺序有什么好处？', 'Tiết kiệm nhiên liệu, giảm thời gian di chuyển và nâng cao tỷ lệ giao đúng giờ (PCR)', 'Không có tác dụng gì', 'Chỉ làm mất thời gian lập kế hoạch', NULL, NULL, NULL, 'Saves fuel, reduces travel time, and improves on-time delivery rate (PCR)', 'No benefit at all', 'Only wastes planning time', NULL, NULL, NULL, '节省燃油、减少行车时间并提高准时派送率（PCR）', '没有任何作用', '只会浪费规划时间', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 5, 2, 'Thời điểm nào là thích hợp nhất để tài xế thực hiện nạp nhiên liệu hoặc vệ sinh xe?', 'When is the best time for a driver to refuel or clean the vehicle?', '司机加油或清洁车辆的最佳时机是什么时候？', 'Trong giờ cao điểm giao nhận hàng', 'Vào thời gian nghỉ giữa ca hoặc ngoài giờ cao điểm', 'Khi khách đang đứng chờ nhận hàng', NULL, NULL, NULL, 'During peak pickup/delivery hours', 'During shift breaks or off-peak hours', 'While a customer is waiting to receive a parcel', NULL, NULL, NULL, '在收发货高峰时段', '在班次休息或非高峰时段', '客户正在等待收货时', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 5, 1, 'Ngay sau khi giao xong 1 kiện hàng cho khách, tài xế cần thực hiện thao tác gì trên App?', 'Right after delivering a parcel, what should the driver do on the app?', '完成一单派送后，司机应在App上进行什么操作？', 'Cập nhật ngay trạng thái ''Đã giao thành công'' để hệ thống ghi nhận Realtime', 'Để đến cuối tuần mới cập nhật một lượt', 'Không cần cập nhật', NULL, NULL, NULL, 'Immediately update ''Delivered successfully'' for real-time tracking', 'Wait until the weekend to update in bulk', 'No need to update', NULL, NULL, NULL, '立即更新「已成功送达」状态以便系统实时记录', '等到周末一次性更新', '无需更新', NULL, NULL, NULL);
