INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 5, 2, 'Ma trận Eisenhower giúp tài xế sắp xếp công việc dựa trên 2 trục nào?', 'The Eisenhower Matrix helps prioritize tasks based on which two axes?', '艾森豪威尔矩阵基于哪两个维度帮助安排任务优先级？', 'Nặng – Nhẹ', 'Khẩn cấp – Quan trọng', 'Xa – Gần', NULL, NULL, NULL, 'Heavy – Light', 'Urgent – Important', 'Far – Near', NULL, NULL, NULL, '重—轻', '紧急—重要', '远—近', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 5, 3, 'VRP (Vehicle Routing Problem) là bài toán toán học liên quan đến vấn đề gì?', 'The Vehicle Routing Problem (VRP) in mathematics deals with what issue?', '数学中的车辆路径问题（VRP）涉及什么内容？', 'Tính lương cho tài xế', 'Định giá cước vận chuyển', 'Tối ưu lộ trình đi qua nhiều điểm giao/nhận với quãng đường ngắn nhất', NULL, NULL, NULL, 'Calculating driver salaries', 'Pricing shipping fees', 'Optimizing routes through multiple stops with the shortest total distance', NULL, NULL, NULL, '计算司机工资', '制定运费价格', '以最短总里程优化经过多个收发点的路线', NULL, NULL, NULL);
