INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 5, 2, 'DHL và FedEx sử dụng phần mềm định tuyến tự động dựa trên thuật toán nào để tính lộ trình tối ưu?', 'DHL and FedEx use automated routing software based on which type of algorithm?', 'DHL和联邦快递使用基于哪种算法的自动路线规划软件？', 'Thuật toán mã hóa dữ liệu (Encryption)', 'Thuật toán dựa trên bài toán VRP', 'Thuật toán nén hình ảnh', NULL, NULL, NULL, 'Data encryption algorithms', 'Algorithms based on the VRP problem', 'Image compression algorithms', NULL, NULL, NULL, '数据加密算法', '基于VRP问题的算法', '图像压缩算法', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 5, 3, 'Tại Việt Nam, GHTK và J&T Express kết hợp hệ thống auto-routing với yếu tố nào để tối đa số đơn giao trong ca?', 'In Vietnam, GHTK and J&T Express combine auto-routing with which factor to maximize deliveries per shift?', '在越南，GHTK和J&T Express将自动路线系统与什么因素结合，以最大化每班次派送量？', 'Giá xăng dầu hàng ngày', 'Số lượng nhân viên văn phòng', 'Khung giờ Cut-off theo từng bưu cục', NULL, NULL, NULL, 'Daily fuel prices', 'Number of office staff', 'Per-hub cut-off times', NULL, NULL, NULL, '每日油价', '办公室员工数量', '各网点的截单时间', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 6, 2, 'Trách nhiệm phối hợp của tài xế với Bộ phận Điều hành giao vận là gì?', 'What is the driver''s coordination responsibility with the Operations department?', '司机与调度部门协作的职责是什么？', 'Chỉ báo cáo vào cuối ngày', 'Cập nhật trạng thái chuyến đi kịp thời (Đã lấy hàng, Đang di chuyển, Đã giao thành công)', 'Tự thay đổi tuyến đường mà không cần thông báo', NULL, NULL, NULL, 'Only report at the end of the day', 'Update trip status promptly (Picked up, In transit, Delivered)', 'Change the route on their own without notifying anyone', NULL, NULL, NULL, '只在一天结束时报告', '及时更新行程状态（已取件、运输中、已送达）', '自行改变路线而不通知任何人', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 6, 2, 'Khi hoàn tất ca làm việc, tài xế có trách nhiệm bàn giao phương tiện như thế nào?', 'At the end of a shift, how should the driver hand over the vehicle?', '班次结束时，司机应如何交接车辆？', 'Đỗ xe tại bãi, để lại chìa khóa mà không cần dọn cabin', 'Vệ sinh cabin/thùng xe, kiểm tra nhiên liệu, bàn giao đầy đủ giấy tờ và báo cáo sự cố nếu có', 'Giao xe trực tiếp cho người ca sau mà không cần đối soát tình trạng', NULL, NULL, NULL, 'Park it and leave the keys without cleaning the cabin', 'Clean the cabin/cargo box, check fuel, hand over full documents, and report any issues', 'Hand it directly to the next shift without checking its condition', NULL, NULL, NULL, '停车留下钥匙，无需清理驾驶室', '清洁驾驶室/货厢，检查油量，交接齐全证件，并报告任何问题', '直接交给下一班次而不核对车况', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 6, 2, 'Trách nhiệm cốt lõi của tài xế khi làm việc với Nhân viên Kho (Warehouse/Sorter) là gì?', 'What is the driver''s core responsibility when working with Warehouse/Sorter staff?', '司机与仓库/分拣人员协作时的核心职责是什么？', 'Tranh giành bưu kiện', 'Kiểm đếm chính xác số lượng, tình trạng bao bì/tem nhãn và ký bàn giao rõ ràng', 'Giao toàn bộ việc chất xếp cho kho', NULL, NULL, NULL, 'Compete over parcels', 'Accurately count quantities, check packaging/label condition, and sign off handovers clearly', 'Leave all loading work entirely to the warehouse', NULL, NULL, NULL, '争抢包裹', '准确清点数量、检查包装/标签状况并清楚签收交接', '把所有装载工作完全交给仓库', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 6, 2, 'Khi phát hiện tuyến đường phía trước bị ngập sâu hoặc kẹt xe đứt đoạn, tài xế nên làm gì cho đội ngũ?', 'Upon discovering deep flooding or gridlock ahead, what should the driver do for the team?', '发现前方道路严重积水或堵塞时，司机应为团队做什么？', 'Giữ bí mật một mình', 'Chủ động chia sẻ thông tin giao thông lên nhóm đội xe để đồng nghiệp tránh đường', 'Xúi các tài xế khác đi vào', NULL, NULL, NULL, 'Keep it a secret', 'Proactively share the traffic info in the fleet group so colleagues can avoid it', 'Encourage other drivers to go that way', NULL, NULL, NULL, '自己保密不说', '主动在车队群里分享交通信息，让同事避开', '怂恿其他司机继续前往', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 6, 2, 'Tinh thần làm việc nhóm (Teamwork) trong đội xe SF Express thể hiện rõ nhất qua hành vi nào?', 'Which behavior best reflects teamwork spirit in the SF Express fleet?', '顺丰车队中，哪种行为最能体现团队合作精神？', 'Chỉ làm xong việc của mình rồi về', 'Sẵn sàng hỗ trợ đồng nghiệp cứu hộ, san hàng khi xe gặp sự cố trên đường', 'So kè số lượng đơn hàng với đồng nghiệp', NULL, NULL, NULL, 'Only finishing your own work and leaving', 'Being ready to help rescue cargo when a colleague''s vehicle breaks down', 'Competing with colleagues over order counts', NULL, NULL, NULL, '只完成自己的工作就下班', '当同事车辆出问题时主动协助抢救货物', '与同事比拼订单数量', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 6, 1, 'Mô hình phát triển nhóm 5 giai đoạn (Forming-Storming-Norming-Performing-Adjourning) do ai đề xuất?', 'Who proposed the 5-stage team development model (Forming-Storming-Norming-Performing-Adjourning)?', '「形成-震荡-规范-高效-解散」五阶段团队发展模型是谁提出的？', 'Bruce Tuckman (1965)', 'Albert Mehrabian', 'Parasuraman, Zeithaml & Berry', NULL, NULL, NULL, 'Bruce Tuckman (1965)', 'Albert Mehrabian', 'Parasuraman, Zeithaml & Berry', NULL, NULL, NULL, 'Bruce Tuckman（1965年）', 'Albert Mehrabian', 'Parasuraman, Zeithaml & Berry', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 6, 3, 'Giai đoạn nào trong mô hình Tuckman thể hiện đội nhóm đã vận hành hiệu quả, phối hợp trơn tru?', 'Which Tuckman stage reflects a team operating effectively with smooth coordination?', '塔克曼模型中，哪个阶段表示团队已经高效运作、配合顺畅？', 'Forming (Hình thành)', 'Storming (Xung đột)', 'Performing (Vận hành hiệu quả)', NULL, NULL, NULL, 'Forming', 'Storming', 'Performing', NULL, NULL, NULL, '形成期 (Forming)', '震荡期 (Storming)', '高效期 (Performing)', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 6, 2, 'PCR (Parcel Completion Rate) là chỉ số phản ánh điều gì?', 'What does the PCR (Parcel Completion Rate) indicator reflect?', 'PCR（派送完成率）指标反映的是什么？', 'Mức lương thưởng của tài xế', 'Tỷ lệ giao hàng thành công, phản ánh hiệu quả phối hợp tài xế – kho – điều hành', 'Số lượng xe trong đội', NULL, NULL, NULL, 'The driver''s salary/bonus level', 'The successful delivery rate, reflecting coordination between driver, warehouse, and operations', 'The number of vehicles in the fleet', NULL, NULL, NULL, '司机的薪资奖金水平', '派送成功率，反映司机-仓库-调度之间的协作效果', '车队车辆数量', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 6, 1, 'Mô hình "trực doanh" (self-operated network) mà SF Express Trung Quốc áp dụng mang lại lợi ích chính nào?', 'What is the main benefit of the "self-operated network" model used by SF Express in China?', '顺丰速运在中国采用的「直营网络」模式带来的主要好处是什么？', 'Kiểm soát chất lượng phối hợp kho vận – tài xế chặt chẽ hơn', 'Giảm toàn bộ chi phí nhân sự về 0', 'Không cần đầu tư vào công nghệ', NULL, NULL, NULL, 'Tighter quality control over warehouse-driver coordination', 'Reducing all personnel costs to zero', 'No need to invest in technology', NULL, NULL, NULL, '更严格地控制仓配-司机协作的质量', '将全部人力成本降为零', '无需在技术上投入', NULL, NULL, NULL);
INSERT INTO question_bank (program_id, module, correct_index, question_vi, question_en, question_zh, option1_vi, option2_vi, option3_vi, option4_vi, option5_vi, option6_vi, option1_en, option2_en, option3_en, option4_en, option5_en, option6_en, option1_zh, option2_zh, option3_zh, option4_zh, option5_zh, option6_zh) VALUES ('', 6, 2, 'Mục đích chính của buổi họp giao ca đầu ngày (briefing) tại các bưu cục là gì?', 'What is the main purpose of a daily morning briefing at hubs?', '网点每日晨会的主要目的是什么？', 'Chỉ để điểm danh nhân sự', 'Đồng bộ thông tin về đơn hàng ưu tiên, tuyến đường thay đổi và lưu ý đặc biệt trong ngày', 'Thay thế hoàn toàn cho việc đào tạo', NULL, NULL, NULL, 'Only to take attendance', 'Align staff on priority orders, route changes, and special notes for the day', 'Completely replace formal training', NULL, NULL, NULL, '只是为了点名', '同步优先订单、路线变更及当日特别注意事项', '完全取代正式培训', NULL, NULL, NULL);
